def merge_dict(d1, d2):
    """Write a function to merge two dictionaries.

    Return a new dictionary containing the items from ``d1`` and ``d2``.
    If a key appears in both, the value from ``d2`` takes precedence.
    Neither input dictionary is modified.
    """
    merged = dict(d1)
    merged.update(d2)
    return merged
